        self._cache = True  # Allow for ``nocache``
        self._data_store = {}
        self._default_timeout = default_timeout
        self._gc_thread_wait = gc_thread_wait
        self._gc_thread = None
        self._do_gc_thread = False
        self._gc_lock = RLock()
        self.counters = {}  # Only enabled with ``debug``

        # Force all calls to use this value instead of default, or what was
        # used during decorator creation.
        self._override_timeout = None

        if default_timeout and not isinstance(default_timeout, int):
            raise ValueError("Default timeout can only be `int`")

        if self._gc_thread_wait and not default_timeout:
            raise ValueError("gc_thread_wait is only valid if default_timeout is > 0")

        if self._gc_thread_wait:
            self._do_gc_thread = True
            self._gc_thread = Thread(target=self._gc)
            self._gc_thread.daemon = True
            self._gc_thread.start()

    # Default stuff to override MutableMapping ABC ############################
    def __len__(self):
        return len([x for x, y in self.items() if y is not INIT_CACHE_VALUE])

    def __getitem__(self, key):
        '''Only return the item if it's not the INIT value'''
        with self._gc_lock:
            if (key not in self._data_store) or (self._data_store[key] is INIT_CACHE_VALUE):
                raise KeyError(key)
            return self._data_store[key]

    def __setitem__(self, key, value):
        with self._gc_lock:
            self._data_store[key] = value

    def __delitem__(self, key):
        with self._gc_lock:
            del self._data_store[key]

    def __iter__(self):
        '''
        Override ``iter()``.  Snapshot the keys first; yielding under a
        non-reentrant lock deadlocks as soon as the loop body touches the cache.
        '''
        with self._gc_lock:
            keys = list(self._data_store.keys())
        for x in keys:
            yield x

    # Override some of the *normal* methods to include the lock ###############
    def clear(self):
        '''Clear the cache'''
        with self._gc_lock:
            self._data_store.clear()
            self.counters.clear()

    def keys(self):
        '''Return a list of keys in the cache'''
        with self._gc_lock:
            return list(self._data_store.keys())

    def items(self):
        '''Return all items in the cache as a list of ``tuple(key, value)``'''
        with self._gc_lock:
            return list(self._data_store.items())

    def values(self):
        '''Return a list of cached values'''
        with self._gc_lock:
            return list(self._data_store.values())

    def pop(self, key):
        '''Remove the cached value specified by ``key``'''
        with self._gc_lock:
            return self._data_store.pop(key)

    def popitem(self):
        '''Remove a random item from the cache (only useful during testing)'''
        with self._gc_lock:
            return self._data_store.popitem()
    ###########################################################################

    @property
    def data_store(self):
        '''Underlying cache mapping (includes not-yet-filled placeholders).'''
        return self._data_store

    @data_store.setter
    def data_store(self, value):
        with self._gc_lock:
            self._data_store = value

    def _is_key_initialized(self, key):
        with self._gc_lock:
            return self._data_store.get(key) is INIT_CACHE_VALUE

    def _from_timestamp(self, timestamp):
        '''Convert a timestamp string to an epoch value'''
        if isinstance(timestamp, (int, float)) and not isinstance(timestamp, bool):
            return float(timestamp)

        text = str(timestamp).strip()
        try:
            return float(text)
        except ValueError:
            pass

        parts = text.split()
        if len(parts) >= 5 and parts[1] in _ASCTIME_MONTHS:
            year = int(parts[4])
            month = _ASCTIME_MONTHS[parts[1]]
            day = int(parts[2])
            hour, minute, second = [int(piece) for piece in parts[3].split(':')]
            return time.mktime((year, month, day, hour, minute, second, 0, 0, -1))

        return time.mktime(time.strptime(text))

    def _to_timestamp(self, epoch=None):
        '''Convert an epoch value to a timestamp string'''
        if epoch is not None:
            return time.asctime(time.localtime(epoch))

        return time.asctime()

    def _debug_print(self, *args):
        if self._debug and not self._quiet:
            print(*args)

    def dump(self):
        '''Dump the entire cache as a JSON string'''
        return json.dumps(self._data_store, indent=4, separators=(',', ': '))

    def _stable_arg(self, name, value):
        '''
        Methods pass the instance as ``self`` or ``cls``.  repr(instance) often
        changes every call or raises while walking the cache, so the same call
        never hits and nothing useful is stored.  The instance id is stable.
        '''
        if name in ('self', 'cls') and not isinstance(value, _PRIMITIVES):
            if isinstance(value, type):
                label = value.__name__
            else:
                label = type(value).__name__
            return '<%s id=%s>' % (label, id(value))
        return value

    def _calculate_key(self, func, cached_key=None, *args, **kwargs):
        '''
        Calculates the cache key based on the function, inputs, and object
        settings.

        :param code func: The function being cached
        :param str cached_key: The `keyed_cache`, if any
        :param *args: Any ``*args`` used to call the function
        :param *kwargs: Any ``*kwargs`` used to call the function
        '''
        if cached_key:
            return cached_key

        plain = _plain_function(func) or func
        if not hasattr(plain, '__code__') and hasattr(plain, '__func__'):
            plain = plain.__func__

        key = {}
        try:
            getter = getattr(inspect, 'getfullargspec', None) or inspect.getargspec
            argspec = getter(plain)
            fargs = list(argspec.args)
            defaults = argspec.defaults
            kwonlydefaults = getattr(argspec, 'kwonlydefaults', None)
        except (TypeError, ValueError, AttributeError):
            code = getattr(plain, '__code__', None)
            fargs = list(code.co_varnames[:len(args)]) if code is not None else []
            defaults = None
            kwonlydefaults = None

        # Load the defaults first, since they may not be in the calling spec.
        if defaults:
            key = dict(zip(fargs[-len(defaults):], defaults))
        if kwonlydefaults:
            key.update(kwonlydefaults)

        # Now load in the arguments.
        key.update(kwargs)
        code = getattr(plain, '__code__', None)
        varnames = code.co_varnames if code is not None else tuple(fargs)
        key.update(dict(zip(varnames, args)))

        normalized = {}
        for name, value in key.items():
            normalized[name] = self._stable_arg(name, value)

        # Sort so repr(dict) cannot change between equal calls.
        try:
            ordered_items = sorted(normalized.items())
        except TypeError:
            ordered_items = sorted(normalized.items(), key=lambda kv: repr(kv[0]))

        try:
            rendered = repr(dict(ordered_items))
        except Exception:
            safe_items = []
            for name, value in ordered_items:
                try:
                    repr(value)
                except Exception:
                    value = '<%s:%s>' % (type(value).__name__, id(value))
                safe_items.append((name, value))
            rendered = repr(dict(safe_items))

        if self._hashing:
            formatted_key = sha224(str(rendered).encode('utf-8')).hexdigest()
        else:
            formatted_key = str(rendered)

        return "{prefix}{name}{join}{formatted_key}".format(
            join=self._key_join,
            prefix=(self._prefix + self._key_join) if self._prefix else '',
            name=getattr(plain, '__name__', 'func'),
            formatted_key=formatted_key
        )

    def _update_counter(self, key):
        '''Keeps track of cache hits'''
        if not self._debug:
            return

        with self._gc_lock:
            if key in self.counters:
                self.counters[key] += 1
            else:
                self.counters[key] = 1

    def _gc(self):
        '''
        This is the garbage collection thread that periodically calls our
        collect method.
        '''
        tnext = time.time() + self._gc_thread_wait
        while self._do_gc_thread:
            if time.time() > tnext:
                self.collect()
                tnext = time.time() + self._gc_thread_wait

            time.sleep(1)

    def _timed_out(self, item):
        timeout = getattr(item, 'timeout', None)
        if not timeout:
            return False
        return time.time() > self._from_timestamp(timeout)

    def collect(self, since=None):
        '''
        Clear any item from the cache that has timed out.
        '''
        remove_keys = []
        for key, item in self.items():
            try:
                timed_out = self._timed_out(item)
                added_after_since = False
                if since and getattr(item, 'time_added', None):
                    added_after_since = self._from_timestamp(item.time_added) > since
            except (AttributeError, ValueError, TypeError, OverflowError):
                continue

            if timed_out or added_after_since:
                self._debug_print('collecting : %s' % key)
                remove_keys.append(key)

        for key in remove_keys:
            try:
                del self[key]
            except KeyError:
                pass

    # Decorators ##############################################################
    def clear_cache(self):
        '''
        A decorator used to clear the cache everytime the function is called.

        For example, let's say you have a "discovery" function that stores
        data read by other functions, and those function use caching.  You want
        to use ``@c.clear_cache()`` for your main function so you don't have
        to worry about cache being stale.
        '''
        def real_decorator(function):
            @wraps(function)
            def wrapper(*args, **kwargs):
                self.clear()
                return function(*args, **kwargs)
            return wrapper
        return real_decorator

    def cached(self, key=None, timeout=None):
        '''
        A decorator used to memoize the return of a function call.

        Usable as ``@cache.cached``, ``@cache.cached()``, or
        ``@cache.cached(key='...', timeout=60)``.
        '''
        # ``@cache.cached`` with no call passes the function in as ``key``.
        descriptor_type = None
        plain_key = _plain_function(key)
        if plain_key is not None:
            if isinstance(key, (classmethod, staticmethod)):
                descriptor_type = type(key)
            key = None
            timeout = None

        if timeout and not isinstance(timeout, int):
            raise ValueError("timeout can only be `int`")
        elif (key in self) or self._is_key_initialized(key):
            # `key in self` will return False if the key either doesn't exist,
            # or it's set to the INIT value.  Therefore, we need to call
            # `_is_key_initialized()` to check that condition.
            raise ValueError("cache key '%s' already exists" % key)
        elif key:
            # Set the default value so we can check for collisions when the
            # next decorator is called.
            self[key] = INIT_CACHE_VALUE

        def real_decorator(function, timeout=timeout):
            outer_type = None
            if isinstance(function, (classmethod, staticmethod)):
                outer_type = type(function)
                function = _plain_function(function) or function
            elif isinstance(function, types.MethodType):
                function = getattr(function, '__func__', function)

            function.__cached_timeout__ = timeout or self._default_timeout

            @wraps(function)
            def wrapper(*args, **kwargs):
                # Check the timeout here, since this is the call and not the
                # instantiation.

                if not self._cache:
                    return function(*args, **kwargs)

                cache_key = self._calculate_key(function, key, *args, **kwargs)

                # Let `override_timeout` do its thing
                if self._override_timeout is not None:
                    effective_timeout = self._override_timeout
                else:
                    effective_timeout = function.__cached_timeout__

                try:
                    if cache_key in self and (self[cache_key] is not INIT_CACHE_VALUE):
                        result = self[cache_key]
                        is_fresh = not result.timeout
                        if result.timeout:
                            try:
                                is_fresh = time.time() <= self._from_timestamp(result.timeout)
                            except (ValueError, TypeError, OverflowError):
                                is_fresh = False

                        if is_fresh:
                            self._debug_print('cache hit : %s' % cache_key)
                            self._update_counter(cache_key)
                            return result.value

                        self._debug_print('cache timeout: %s' % cache_key)
                        result = CachedItem(
                            value=function(*args, **kwargs),
                            timeout=self._to_timestamp(time.time() + effective_timeout) if effective_timeout else None,
                            time_added=self._to_timestamp())
                        self[cache_key] = result
                        return result.value
                except KeyError:  # pragma: nocover
                    # Workaround for threading issues, as opposed to a potential
                    # lock block.  A thread may have deleted this key, and
                    # that's fine.  We simply need to cache it again.
                    # We won't always hit this, so we disable code coverage.
                    self._debug_print('KeyError %s' % cache_key)

                self._debug_print('caching %s' % cache_key)

                result = CachedItem(
                    value=function(*args, **kwargs),
                    timeout=self._to_timestamp(time.time() + effective_timeout) if effective_timeout else None,
                    time_added=self._to_timestamp())
                self[cache_key] = result
                return result.value

            if outer_type is not None:
                return outer_type(wrapper)
            return wrapper

        if plain_key is not None:
            wrapped = real_decorator(plain_key)
            if descriptor_type is not None:
                return descriptor_type(wrapped)
            return wrapped
        return real_decorator

    def serialize(self, filename):
        '''
        Serialize the cache to a filename.  This process uses ``pickle``; Do
        not use this function if you are caching something that is not
        picklable!
        '''
        with self._gc_lock:
            payload = dict(self._data_store)
        with open(filename, 'wb') as fh:
            pickle.dump(payload, fh, -1)

    def deserialize(self, filename):
        '''
        Read the serialized cache data from a file.
        '''
        with open(filename, 'rb') as fh:
            data = pickle.load(fh)
        with self._gc_lock:
            self._data_store = data

#!/usr/bin/env python
# coding: utf-8
'''
yamicache : Yet another in-memory cache module ('yami' sounds better to me than
'yaim')

This module provides a simple in-memory interface for caching results from
function calls.
'''

# Imports #####################################################################
from __future__ import print_function
import json
import time
import inspect
import types
import contextlib
import collections
from hashlib import sha224
from functools import wraps
from threading import RLock, Thread
try:
    import cPickle as pickle
except ImportError:
    import pickle
try:
    from collections.abc import MutableMapping
except ImportError:  # pragma: no cover
    from collections import MutableMapping


# Globals #####################################################################
__all__ = ['Cache', 'nocache', 'override_timeout']

_ASCTIME_MONTHS = {
    'Jan': 1, 'Feb': 2, 'Mar': 3, 'Apr': 4, 'May': 5, 'Jun': 6,
    'Jul': 7, 'Aug': 8, 'Sep': 9, 'Oct': 10, 'Nov': 11, 'Dec': 12,
}


def _plain_function(obj):
    '''Unwrap a function, bound method, classmethod, or staticmethod.'''
    if isinstance(obj, types.FunctionType):
        return obj
    if isinstance(obj, types.MethodType):
        return getattr(obj, '__func__', obj)
    if isinstance(obj, (classmethod, staticmethod)):
        func = getattr(obj, '__func__', None)
        if isinstance(func, types.FunctionType):
            return func
        try:
            got = obj.__get__(None, type)
        except Exception:
            return None
        if isinstance(got, types.MethodType):
            return getattr(got, '__func__', None)
        if isinstance(got, types.FunctionType):
            return got
    return None


@contextlib.contextmanager
def override_timeout(cache_obj, timeout):
    cache_obj._override_timeout = timeout

    try:
        yield
    finally:
        # The value of ``None`` disable the override timeout mechanism
        cache_obj._override_timeout = None


@contextlib.contextmanager
def nocache(cache_obj):
    '''
    Use this context manager to temporarily disable all caching for an
    object.

    Example:

        >>> from yamicache import Cache, nocache
        >>> c = Cache()
        >>> @c.cached
        ... def test():
        ...     return 4
        ...
        >>> with nocache(c):
        ...     test()
        ...
        4
        >>> print(c.data_store)
        {}
        >>>

    '''
    cache_obj._cache = False

    try:
        yield
    finally:
        # ``_cache`` is the flag the wrapper checks.  Writing ``cache`` left
        # caching disabled, so calls after this block stored nothing.
        cache_obj._cache = True


CachedItem = collections.namedtuple('CachedItem', 'value timeout time_added')
INIT_CACHE_VALUE = CachedItem("<value not cached yet>", None, None)


class Cache(MutableMapping):
    '''
    A class for caching and retreiving returns from function calls.

    :param bool hashing: Whether or not to hash the function inputs when
        calculating the key.  This helps keep the keys *readable*, especially
        for functions with many inputs.
    :param str key_join: The character used to join the different parts that
        make up the hash key.
    :param bool debug: When ``True``, ``Cache.counters`` will be enabled and
        cache hits will produce output on ``stdout``.
    :param str prefix: All cache keys will use this prefix.  Since the current
        implementation is instance-based, this is only helpful if dumping or
        comparing the cache to another instance.
    :param bool quiet: Don't print during ``debug`` cache hits
    :param int default_timeout: If > 0, all cached items will be considered
        stale this many seconds after they are cached.  In that case, the
        function will be run again, cached, and a new timeout value will be
        created.
    :param int gc_thread_wait: The number of seconds in between cache
        *garbage collection*.  The default, ``None``, will disable the garbage
        collection thread.  This parameter is only valid if ``default_timeout``
        is > 0 (``ValueError`` is raised otherwise).
    '''
    def __init__(
        self, hashing=True, key_join='|', debug=False, prefix=None,
        quiet=False, default_timeout=0, gc_thread_wait=None
    ):
        self._prefix = prefix or ''
        self._hashing = hashing
        self._key_join = key_join
        self._debug = debug
        self._quiet = quiet
        self._cache = True  # Allow for ``nocache``
        self._data_store = {}
        self._default_timeout = default_timeout
        self._gc_thread_wait = gc_thread_wait
        self._gc_thread = None
        self._do_gc_thread = False
        self._gc_lock = RLock()
        self.counters = {}  # Only enabled with ``debug``

        # Force all calls to use this value instead of default, or what was
        # used during decorator creation.
        self._override_timeout = None

        if default_timeout and not isinstance(default_timeout, int):
            raise ValueError("Default timeout can only be `int`")

        if self._gc_thread_wait:
            self._do_gc_thread = True
            self._gc_thread = Thread(target=self._gc)
            self._gc_thread.daemon = True
            self._gc_thread.start()

    # Default stuff to override MutableMapping ABC ############################
    def __len__(self):
        return len([x for x, y in self.items() if y is not INIT_CACHE_VALUE])

    def __getitem__(self, key):
        '''Only return the item if it's not the INIT value'''
        with self._gc_lock:
            if (key not in self._data_store) or (self._data_store[key] is INIT_CACHE_VALUE):
                raise KeyError(key)
            return self._data_store[key]

    def __setitem__(self, key, value):
        with self._gc_lock:
            self._data_store[key] = value

    def __delitem__(self, key):
        with self._gc_lock:
            del self._data_store[key]

    def __iter__(self):
        '''
        Override ``iter()``.  Snapshot keys so the lock is not held across
        yield (a non-reentrant lock deadlocks if the caller reads the cache).
        '''
        with self._gc_lock:
            keys = list(self._data_store.keys())
        for x in keys:
            yield x

    # Override some of the *normal* methods to include the lock ###############
    def clear(self):
        '''Clear the cache'''
        with self._gc_lock:
            self._data_store.clear()
            self.counters.clear()

    def keys(self):
        '''Return a list of keys in the cache'''
        with self._gc_lock:
            return list(self._data_store.keys())

    def items(self):
        '''Return all items in the cache as a list of ``tuple(key, value)``'''
        with self._gc_lock:
            return list(self._data_store.items())

    def values(self):
        '''Return a list of cached values'''
        with self._gc_lock:
            return list(self._data_store.values())

    def pop(self, key):
        '''Remove the cached value specified by ``key``'''
        with self._gc_lock:
            return self._data_store.pop(key)

    def popitem(self):
        '''Remove a random item from the cache (only useful during testing)'''
        with self._gc_lock:
            return self._data_store.popitem()
    ###########################################################################

    @property
    def data_store(self):
        '''Underlying cache mapping (includes not-yet-filled placeholders).'''
        return self._data_store

    @data_store.setter
    def data_store(self, value):
        with self._gc_lock:
            self._data_store = value

    def _is_key_initialized(self, key):
        with self._gc_lock:
            return self._data_store.get(key) is INIT_CACHE_VALUE

    def _from_timestamp(self, timestamp):
        '''Convert a timestamp string to an epoch value'''
        if isinstance(timestamp, (int, float)) and not isinstance(timestamp, bool):
            return float(timestamp)

        text = str(timestamp).strip()
        try:
            # Original path.  Kept first so ordinary timestamps round-trip
            # exactly as time.strptime + time.mktime did.
            return time.mktime(time.strptime(text))
        except (TypeError, ValueError):
            pass

        # asctime() space-pads the day ("Jan  1") and is always English, which
        # strptime() rejects under a non-C locale or on single-digit days.
        parts = text.split()
        if len(parts) >= 5 and parts[1] in _ASCTIME_MONTHS:
            year = int(parts[4])
            month = _ASCTIME_MONTHS[parts[1]]
            day = int(parts[2])
            hour, minute, second = [int(piece) for piece in parts[3].split(':')]
            return time.mktime((year, month, day, hour, minute, second, 0, 0, -1))

        return time.mktime(time.strptime(text))

    def _to_timestamp(self, epoch=None):
        '''Convert an epoch value to a timestamp string'''
        if epoch:
            return time.asctime(time.localtime(epoch))

        return time.asctime()

    def _debug_print(self, *args):
        if self._debug and not self._quiet:
            print(*args)

    def dump(self):
        '''Dump the entire cache as a JSON string'''
        return json.dumps(self._data_store, indent=4, separators=(',', ': '))

    def _calculate_key(self, func, cached_key=None, *args, **kwargs):
        '''
        Calculates the cache key based on the function, inputs, and object
        settings.

        :param code func: The function being cached
        :param str cached_key: The `keyed_cache`, if any
        :param *args: Any ``*args`` used to call the function
        :param *kwargs: Any ``*kwargs`` used to call the function
        '''
        if cached_key:
            return cached_key

        plain = _plain_function(func) or func
        if not hasattr(plain, '__code__') and hasattr(plain, '__func__'):
            plain = plain.__func__

        key = {}
        try:
            # getargspec() is removed on modern Python and rejects annotations
            # and keyword-only arguments, which aborted the call before store.
            getter = getattr(inspect, 'getfullargspec', None) or inspect.getargspec
            argspec = getter(plain)
            fargs = list(argspec.args)
            defaults = argspec.defaults
            kwonlydefaults = getattr(argspec, 'kwonlydefaults', None)
        except (TypeError, ValueError, AttributeError):
            code = getattr(plain, '__code__', None)
            fargs = list(code.co_varnames[:len(args)]) if code is not None else []
            defaults = None
            kwonlydefaults = None

        # Load the defaults first, since they may not be in the calling spec.
        if defaults:
            key = dict(zip(fargs[-len(defaults):], defaults))
        if kwonlydefaults:
            key.update(kwonlydefaults)

        # Now load in the arguments.
        key.update(kwargs)
        code = getattr(plain, '__code__', None)
        varnames = code.co_varnames if code is not None else tuple(fargs)
        key.update(dict(zip(varnames, args)))

        # Python may re-order the keys when we go to repr them.  This will
        # cause invalid cache misses.  Recreate the dict with a known order.
        # If a method's ``self`` cannot be ordered or repr'd, still cache the
        # call instead of raising and leaving the store empty.
        try:
            rendered = repr(dict(sorted(key.items())))
        except TypeError:
            rendered = repr(dict(sorted(key.items(), key=lambda kv: repr(kv[0]))))
        except Exception:
            safe_items = []
            for name, value in key.items():
                try:
                    repr(value)
                except Exception:
                    value = '<%s:%s>' % (type(value).__name__, id(value))
                safe_items.append((name, value))
            try:
                safe_items = sorted(safe_items)
            except TypeError:
                safe_items = sorted(safe_items, key=lambda kv: repr(kv[0]))
            rendered = repr(dict(safe_items))

        formatted_key = (
            sha224(str(rendered).encode('utf-8')).hexdigest()
            if self._hashing else str(rendered)
        )

        return "{prefix}{name}{join}{formatted_key}".format(
            join=self._key_join,
            prefix=(self._prefix + self._key_join) if self._prefix else '',
            name=getattr(plain, '__name__', 'func'),
            formatted_key=formatted_key
        )

    def _update_counter(self, key):
        '''Keeps track of cache hits'''
        if not self._debug:
            return

        with self._gc_lock:
            if key in self.counters:
                self.counters[key] += 1
            else:
                self.counters[key] = 1

    def _gc(self):
        '''
        This is the garbage collection thread that periodically calls our
        collect method.
        '''
        tnext = time.time() + self._gc_thread_wait
        while self._do_gc_thread:
            if time.time() > tnext:
                self.collect()
                tnext = time.time() + self._gc_thread_wait

            time.sleep(1)

    def collect(self, since=None):
        '''
        Clear any item from the cache that has timed out.
        '''
        remove_keys = []
        for key, item in self.items():
            try:
                timed_out = bool(
                    item.timeout and
                    (time.time() > self._from_timestamp(item.timeout))
                )
                added_after_since = False
                if since and item.time_added:
                    added_after_since = self._from_timestamp(item.time_added) > since
            except (AttributeError, ValueError, TypeError, OverflowError):
                continue

            if timed_out or added_after_since:
                self._debug_print('collecting : %s' % key)
                remove_keys.append(key)

        for key in remove_keys:
            if key in self:
                del self[key]

    # Decorators ##############################################################
    def clear_cache(self):
        '''
        A decorator used to clear the cache everytime the function is called.

        For example, let's say you have a "discovery" function that stores
        data read by other functions, and those function use caching.  You want
        to use ``@c.clear_cache()`` for your main function so you don't have
        to worry about cache being stale.
        '''
        def real_decorator(function):
            @wraps(function)
            def wrapper(*args, **kwargs):
                self.clear()
                return function(*args, **kwargs)
            return wrapper
        return real_decorator

    def cached(self, key=None, timeout=None):
        '''
        A decorator used to memoize the return of a function call.

        Usable as ``@cache.cached``, ``@cache.cached()``, or
        ``@cache.cached(key='...', timeout=60)``.
        '''
        # @cache.cached (no parentheses) passes the callable itself as ``key``.
        descriptor_type = None
        plain_key = _plain_function(key)
        if plain_key is not None:
            if isinstance(key, (classmethod, staticmethod)):
                descriptor_type = type(key)
            key = None
            timeout = None

        if timeout and not isinstance(timeout, int):
            raise ValueError("timeout can only be `int`")
        elif (key in self) or self._is_key_initialized(key):
            # `key in self` will return False if the key either doesn't exist,
            # or it's set to the INIT value.  Therefore, we need to call
            # `_is_key_initialized()` to check that condition.
            raise ValueError("cache key '%s' already exists" % key)
        elif key:
            # Set the default value so we can check for collisions when the
            # next decorator is called.
            self[key] = INIT_CACHE_VALUE

        def real_decorator(function, timeout=timeout):
            outer_type = None
            if isinstance(function, (classmethod, staticmethod)):
                outer_type = type(function)
                unwrapped = _plain_function(function)
                if unwrapped is not None:
                    function = unwrapped
            elif isinstance(function, types.MethodType):
                function = getattr(function, '__func__', function)

            function.__cached_timeout__ = timeout or self._default_timeout

            @wraps(function)
            def wrapper(*args, **kwargs):
                # Check the timeout here, since this is the call and not the
                # instantiation.

                if not self._cache:
                    return function(*args, **kwargs)

                cache_key = self._calculate_key(function, key, *args, **kwargs)

                # Let `override_timeout` do its thing
                if self._override_timeout is not None:
                    timeout = self._override_timeout
                else:
                    timeout = function.__cached_timeout__

                try:
                    if cache_key in self and (self[cache_key] is not INIT_CACHE_VALUE):
                        result = self[cache_key]
                        if (not result.timeout) or (result.timeout and (time.time() <= self._from_timestamp(result.timeout))):
                            self._debug_print('cache hit : %s' % cache_key)
                            self._update_counter(cache_key)
                            return result.value
                        elif result.timeout and (time.time() > self._from_timestamp(result.timeout)):
                            self._debug_print('cache timeout: %s' % cache_key)
                            result = CachedItem(
                                value=function(*args, **kwargs),
                                timeout=self._to_timestamp(time.time() + timeout) if timeout else None,
                                time_added=self._to_timestamp())
                            self[cache_key] = result
                            return self[cache_key].value
                except KeyError:  # pragma: nocover
                    # Workaround for threading issues, as opposed to a potential
                    # lock block.  A thread may have deleted this key, and
                    # that's fine.  We simply need to cache it again.
                    # We won't always hit this, so we disable code coverage.
                    self._debug_print('KeyError %s' % cache_key)
                except (ValueError, TypeError, OverflowError):
                    # A bad timestamp must not skip the store; treat as a miss.
                    self._debug_print('cache timeout: %s' % cache_key)

                self._debug_print('caching %s' % cache_key)

                result = CachedItem(
                    value=function(*args, **kwargs),
                    timeout=self._to_timestamp(time.time() + timeout) if timeout else None,
                    time_added=self._to_timestamp())
                self[cache_key] = result
                return result.value

            if outer_type is not None:
                return outer_type(wrapper)
            return wrapper

        if plain_key is not None:
            wrapped = real_decorator(plain_key)
            if descriptor_type is not None:
                return descriptor_type(wrapped)
            return wrapped
        return real_decorator

    def serialize(self, filename):
        '''
        Serialize the cache to a filename.  This process uses ``pickle``; Do
        not use this function if you are caching something that is not
        picklable!
        '''
        with open(filename, 'wb') as fh:
            pickle.dump(self._data_store, fh, -1)

    def deserialize(self, filename):
        '''
        Read the serialized cache data from a file.
        '''
        with open(filename, 'rb') as fh:
            self._data_store = pickle.load(fh)

