def _unwrap(obj):
    '''Return the plain function for a function, method, classmethod, or staticmethod.'''
    if isinstance(obj, types.FunctionType):
        return obj
    if isinstance(obj, types.MethodType):
        return getattr(obj, '__func__', obj)
    if isinstance(obj, classmethod):
        func = getattr(obj, '__func__', None)
        if isinstance(func, types.FunctionType):
            return func
        try:
            bound = obj.__get__(None, type)
            return getattr(bound, '__func__', None)
        except Exception:
            return None
    if isinstance(obj, staticmethod):
        func = getattr(obj, '__func__', None)
        if isinstance(func, types.FunctionType):
            return func
        try:
            got = obj.__get__(None, type)
        except Exception:
            return None
        return got if isinstance(got, types.FunctionType) else None
