        try:
            ordered = sorted(key.items())
        except TypeError:
            ordered = sorted(key.items(), key=lambda kv: repr(kv[0]))

        safe = []
        for name, value in ordered:
            try:
                repr(value)
            except Exception:
                value = '<%s:%s>' % (type(value).__name__, id(value))
            safe.append((name, value))
        rendered = repr(dict(safe))

        if self._hashing:
            formatted_key = sha224(str(rendered).encode('utf-8')).hexdigest()
        else:
            formatted_key = str(rendered)

        return "{prefix}{name}{join}{formatted_key}".format(
            join=self._key_join,
            prefix=(self._prefix + self._key_join) if self._prefix else '',
            name=getattr(plain, '__name__', 'func'),
            formatted_key=formatted_key
        )

    def _update_counter(self, key):
        '''Keeps track of cache hits'''
        if not self._debug:
            return

        with self._gc_lock:
            if key in self.counters:
                self.counters[key] += 1
            else:
                self.counters[key] = 1

    def _gc(self):
        '''
        This is the garbage collection thread that periodically calls our
        collect method.
        '''
        tnext = time.time() + self._gc_thread_wait
        while self._do_gc_thread:
            if time.time() > tnext:
                self.collect()
                tnext = time.time() + self._gc_thread_wait

            time.sleep(1)

    def collect(self, since=None):
        '''
        Clear any item from the cache that has timed out.
        '''
        remove_keys = []
        for key, item in self.items():
            try:
                timed_out = bool(
                    getattr(item, 'timeout', None) and
                    (time.time() > self._from_timestamp(item.timeout))
                )
                added_after_since = False
                if since and getattr(item, 'time_added', None):
                    added_after_since = self._from_timestamp(item.time_added) > since
            except (AttributeError, ValueError, TypeError, OverflowError):
                continue

            if timed_out or added_after_since:
                self._debug_print('collecting : %s' % key)
                remove_keys.append(key)

        for key in remove_keys:
            try:
                del self[key]
            except KeyError:
                pass

    # Decorators ##############################################################
    def clear_cache(self):
        '''
        A decorator used to clear the cache everytime the function is called.

        For example, let's say you have a "discovery" function that stores
        data read by other functions, and those function use caching.  You want
        to use ``@c.clear_cache()`` for your main function so you don't have
        to worry about cache being stale.
        '''
        def real_decorator(function):
            @wraps(function)
            def wrapper(*args, **kwargs):
                self.clear()
                return function(*args, **kwargs)
            return wrapper
        return real_decorator

    def cached(self, key=None, timeout=None):
        '''
        A decorator used to memoize the return of a function call.

        Usable as ``@cache.cached``, ``@cache.cached()``, or
        ``@cache.cached(key='...', timeout=60)``.
        '''
        descriptor_type = None
        plain_key = _unwrap(key)
        if plain_key is not None:
            if isinstance(key, (classmethod, staticmethod)):
                descriptor_type = type(key)
            key = None
            timeout = None

        if timeout and not isinstance(timeout, int):
            raise ValueError("timeout can only be `int`")
        elif (key in self) or self._is_key_initialized(key):
            # `key in self` will return False if the key either doesn't exist,
            # or it's set to the INIT value.  Therefore, we need to call
            # `_is_key_initialized()` to check that condition.
            raise ValueError("cache key '%s' already exists" % key)
        elif key:
            # Set the default value so we can check for collisions when the
            # next decorator is called.
            self[key] = INIT_CACHE_VALUE

        def real_decorator(function, timeout=timeout):
            outer_type = None
            if isinstance(function, (classmethod, staticmethod)):
                outer_type = type(function)
                unwrapped = _unwrap(function)
                if unwrapped is not None:
                    function = unwrapped
            elif isinstance(function, types.MethodType):
                function = getattr(function, '__func__', function)

            function.__cached_timeout__ = timeout or self._default_timeout

            @wraps(function)
            def wrapper(*args, **kwargs):
                if not self._cache:
                    return function(*args, **kwargs)

                cache_key = self._calculate_key(function, key, *args, **kwargs)

                if self._override_timeout is not None:
                    use_timeout = self._override_timeout
                else:
                    use_timeout = function.__cached_timeout__

                cached_item = None
                try:
                    if cache_key in self and (self[cache_key] is not INIT_CACHE_VALUE):
                        cached_item = self[cache_key]
                except KeyError:  # pragma: nocover
                    self._debug_print('KeyError %s' % cache_key)

                if cached_item is not None:
                    is_fresh = not cached_item.timeout
                    if cached_item.timeout:
                        try:
                            is_fresh = time.time() <= self._from_timestamp(cached_item.timeout)
                        except (ValueError, TypeError, OverflowError):
                            is_fresh = False
                    if is_fresh:
                        self._debug_print('cache hit : %s' % cache_key)
                        self._update_counter(cache_key)
                        return cached_item.value

                    self._debug_print('cache timeout: %s' % cache_key)
                    refreshed = CachedItem(
                        value=function(*args, **kwargs),
                        timeout=self._to_timestamp(time.time() + use_timeout) if use_timeout else None,
                        time_added=self._to_timestamp())
                    self[cache_key] = refreshed
                    return refreshed.value

                self._debug_print('caching %s' % cache_key)
                result = CachedItem(
                    value=function(*args, **kwargs),
                    timeout=self._to_timestamp(time.time() + use_timeout) if use_timeout else None,
                    time_added=self._to_timestamp())
                self[cache_key] = result
                return result.value

            if outer_type is not None:
                return outer_type(wrapper)
            return wrapper

        if plain_key is not None:
            wrapped = real_decorator(plain_key)
            if descriptor_type is not None:
                return descriptor_type(wrapped)
            return wrapped
        return real_decorator

    def serialize(self, filename):
        '''
        Serialize the cache to a filename.  This process uses ``pickle``; Do
        not use this function if you are caching something that is not
        picklable!
        '''
        with open(filename, 'wb') as fh:
            pickle.dump(self._data_store, fh, -1)

    def deserialize(self, filename):
        '''
        Read the serialized cache data from a file.
        '''
        with open(filename, 'rb') as fh:
            self._data_store = pickle.load(fh)

#!/usr/bin/env python
# coding: utf-8
'''
yamicache : Yet another in-memory cache module ('yami' sounds better to me than
'yaim')

This module provides a simple in-memory interface for caching results from
function calls.
'''

# Imports #####################################################################
from __future__ import print_function
import json
import time
import inspect
import types
import contextlib
import collections
from hashlib import sha224
from functools import wraps
from threading import RLock, Thread
try:
    import cPickle as pickle
except ImportError:
    import pickle
try:
    from collections.abc import MutableMapping
except ImportError:  # pragma: no cover
    from collections import MutableMapping


# Globals #####################################################################
__all__ = ['Cache', 'nocache', 'override_timeout']

# asctime() is always English and space-pads the day ("Jan  1").
# strptime() is locale-aware and rejects that, which made every later call
# look expired so hits were never counted.
_ASCTIME_MONTHS = {
    'Jan': 1, 'Feb': 2, 'Mar': 3, 'Apr': 4, 'May': 5, 'Jun': 6,
    'Jul': 7, 'Aug': 8, 'Sep': 9, 'Oct': 10, 'Nov': 11, 'Dec': 12,
}
_PRIMITIVES = (type(None), bool, int, float, str, bytes)


def _function_of(obj):
    '''Plain function behind a function, method, classmethod, or staticmethod.'''
    if isinstance(obj, types.FunctionType):
        return obj
    if isinstance(obj, types.MethodType):
        return getattr(obj, '__func__', None) or getattr(obj, 'im_func', None)
    if isinstance(obj, (classmethod, staticmethod)):
        func = getattr(obj, '__func__', None)
        if isinstance(func, types.FunctionType):
            return func
        try:
            got = obj.__get__(None, type)
        except Exception:
            return None
        if isinstance(got, types.MethodType):
            return getattr(got, '__func__', None) or getattr(got, 'im_func', None)
        if isinstance(got, types.FunctionType):
            return got
    return None


def _bound_self(obj):
    '''Instance/class a method is bound to, if any.'''
    if isinstance(obj, types.MethodType):
        owner = getattr(obj, '__self__', None)
        if owner is None:
            owner = getattr(obj, 'im_self', None)
        return owner
    return None


@contextlib.contextmanager
def override_timeout(cache_obj, timeout):
    cache_obj._override_timeout = timeout

    try:
        yield
    finally:
        # The value of ``None`` disable the override timeout mechanism
        cache_obj._override_timeout = None


@contextlib.contextmanager
def nocache(cache_obj):
    '''
    Use this context manager to temporarily disable all caching for an
    object.

    Example:

        >>> from yamicache import Cache, nocache
        >>> c = Cache()
        >>> @c.cached
        ... def test():
        ...     return 4
        ...
        >>> with nocache(c):
        ...     test()
        ...
        4
        >>> print(c.data_store)
        {}
        >>>

    '''
    cache_obj._cache = False

    try:
        yield
    finally:
        # The wrapper reads ``_cache``.  Restoring ``cache`` left caching off,
        # so later calls stored nothing.
        cache_obj._cache = True


CachedItem = collections.namedtuple('CachedItem', 'value timeout time_added')
INIT_CACHE_VALUE = CachedItem("<value not cached yet>", None, None)


class Cache(MutableMapping):
    '''
    A class for caching and retreiving returns from function calls.

    :param bool hashing: Whether or not to hash the function inputs when
        calculating the key.  This helps keep the keys *readable*, especially
        for functions with many inputs.
    :param str key_join: The character used to join the different parts that
        make up the hash key.
    :param bool debug: When ``True``, ``Cache.counters`` will be enabled and
        cache hits will produce output on ``stdout``.
    :param str prefix: All cache keys will use this prefix.  Since the current
        implementation is instance-based, this is only helpful if dumping or
        comparing the cache to another instance.
    :param bool quiet: Don't print during ``debug`` cache hits
    :param int default_timeout: If > 0, all cached items will be considered
        stale this many seconds after they are cached.  In that case, the
        function will be run again, cached, and a new timeout value will be
        created.
    :param int gc_thread_wait: The number of seconds in between cache
        *garbage collection*.  The default, ``None``, will disable the garbage
        collection thread.  This parameter is only valid if ``default_timeout``
        is > 0 (``ValueError`` is raised otherwise).
    '''
    def __init__(
        self, hashing=True, key_join='|', debug=False, prefix=None,
        quiet=False, default_timeout=0, gc_thread_wait=None
    ):
        self._prefix = prefix or ''
        self._hashing = hashing
        self._key_join = key_join
        self._debug = debug
        self._quiet = quiet
        self._cache = True  # Allow for ``nocache``
        self._data_store = {}
        # Exact expiry (epoch) so asctime's 1-second truncation cannot drop a
        # fresh entry or skip a hit.
        self._expiry = {}
        self._default_timeout = default_timeout
        self._gc_thread_wait = gc_thread_wait
        self._gc_thread = None
        self._do_gc_thread = False
        self._gc_lock = RLock()
        self.counters = {}  # Only enabled with ``debug``

        # Force all calls to use this value instead of default, or what was
        # used during decorator creation.
        self._override_timeout = None

        if default_timeout and not isinstance(default_timeout, int):
            raise ValueError("Default timeout can only be `int`")

        if self._gc_thread_wait and not default_timeout:
            raise ValueError("gc_thread_wait is only valid if default_timeout is > 0")

        if self._gc_thread_wait:
            self._do_gc_thread = True
            self._gc_thread = Thread(target=self._gc)
            self._gc_thread.daemon = True
            self._gc_thread.start()

    # Default stuff to override MutableMapping ABC ############################
    def __len__(self):
        return len([x for x, y in self.items() if y is not INIT_CACHE_VALUE])

    def __getitem__(self, key):
        '''Only return the item if it's not the INIT value'''
        with self._gc_lock:
            if (key not in self._data_store) or (self._data_store[key] is INIT_CACHE_VALUE):
                raise KeyError(key)
            return self._data_store[key]

    def __setitem__(self, key, value):
        with self._gc_lock:
            self._data_store[key] = value

    def __delitem__(self, key):
        with self._gc_lock:
            del self._data_store[key]
            self._expiry.pop(key, None)

    def __iter__(self):
        '''
        Override ``iter()``.  Snapshot the keys; holding the lock across yield
        deadlocks as soon as the caller touches the cache.
        '''
        with self._gc_lock:
            keys = list(self._data_store.keys())
        for x in keys:
            yield x

    # Override some of the *normal* methods to include the lock ###############
    def clear(self):
        '''Clear the cache and leave caching enabled for later calls.'''
        with self._gc_lock:
            self._data_store.clear()
            self.counters.clear()
            self._expiry.clear()
            self._cache = True

    def keys(self):
        '''Return a list of keys in the cache'''
        with self._gc_lock:
            return list(self._data_store.keys())

    def items(self):
        '''Return all items in the cache as a list of ``tuple(key, value)``'''
        with self._gc_lock:
            return list(self._data_store.items())

    def values(self):
        '''Return a list of cached values'''
        with self._gc_lock:
            return list(self._data_store.values())

    def pop(self, key):
        '''Remove the cached value specified by ``key``'''
        with self._gc_lock:
            self._expiry.pop(key, None)
            return self._data_store.pop(key)

    def popitem(self):
        '''Remove a random item from the cache (only useful during testing)'''
        with self._gc_lock:
            key, value = self._data_store.popitem()
            self._expiry.pop(key, None)
            return key, value
    ###########################################################################

    @property
    def data_store(self):
        '''Underlying cache mapping (includes not-yet-filled placeholders).'''
        return self._data_store

    @data_store.setter
    def data_store(self, value):
        with self._gc_lock:
            self._data_store = value
            self._expiry.clear()

    def _is_key_initialized(self, key):
        with self._gc_lock:
            return self._data_store.get(key) is INIT_CACHE_VALUE

    def _from_timestamp(self, timestamp):
        '''Convert a timestamp string to an epoch value'''
        if isinstance(timestamp, (int, float)) and not isinstance(timestamp, bool):
            return float(timestamp)

        text = str(timestamp).strip()
        head = text.split(None, 1)[0]
        try:
            return float(head)
        except ValueError:
            pass

        try:
            return time.mktime(time.strptime(text))
        except (TypeError, ValueError):
            pass

        parts = text.split()
        if len(parts) >= 5 and parts[1] in _ASCTIME_MONTHS:
            year = int(parts[4])
            month = _ASCTIME_MONTHS[parts[1]]
            day = int(parts[2])
            hour, minute, second = [int(piece) for piece in parts[3].split(':')]
            return time.mktime((year, month, day, hour, minute, second, 0, 0, -1))

        return time.mktime(time.strptime(text))

    def _to_timestamp(self, epoch=None):
        '''Convert an epoch value to a timestamp string'''
        if epoch:
            return time.asctime(time.localtime(epoch))

        return time.asctime()

    def _debug_print(self, *args):
        if self._debug and not self._quiet:
            print(*args)

    def dump(self):
        '''Dump the entire cache as a JSON string'''
        return json.dumps(self._data_store, indent=4, separators=(',', ': '))

    def _stable_value(self, name, value):
        '''
        ``self``/``cls`` must not go through ``repr``.  A class instance's
        repr often changes every call or raises while walking the cache, so
        the call throws before the result is stored.
        '''
        if name in ('self', 'cls') and not isinstance(value, _PRIMITIVES):
            if isinstance(value, type):
                label = value.__name__
            else:
                label = type(value).__name__
            return '<%s id=%s>' % (label, id(value))
        return value

    def _signature(self, func):
        try:
            getter = getattr(inspect, 'getfullargspec', None) or inspect.getargspec
            spec = getter(func)
            return spec
        except (TypeError, ValueError, AttributeError):
            return None

    def _bind_arguments(self, func, args, kwargs):
        '''Map a call onto parameter names.  Never raises.'''
        owner = _bound_self(func)
        plain = _function_of(func) or func
        if owner is not None and (not args or args[0] is not owner):
            args = (owner,) + tuple(args)

        if not hasattr(plain, '__code__') and hasattr(plain, '__func__'):
            plain = plain.__func__

        key = {}
        spec = self._signature(plain)
        if spec is not None:
            fargs = list(spec.args)
            defaults = spec.defaults
            kwdefaults = getattr(spec, 'kwonlydefaults', None)
            varargs = getattr(spec, 'varargs', None)
        else:
            code = getattr(plain, '__code__', None)
            fargs = list(code.co_varnames[:code.co_argcount]) if code is not None else []
            defaults = None
            kwdefaults = None
            varargs = None

        if defaults:
            key.update(dict(zip(fargs[-len(defaults):], defaults)))
        if kwdefaults:
            key.update(kwdefaults)
        key.update(kwargs)

        for name, value in zip(fargs, args):
            key[name] = value
        if varargs and len(args) > len(fargs):
            key[varargs] = args[len(fargs):]

        stable = {}
        for name, value in key.items():
            try:
                stable[name] = self._stable_value(name, value)
            except Exception:
                stable[name] = '<%s:%s>' % (type(value).__name__, id(value))
        return plain, stable

    def _render_mapping(self, mapping):
        try:
            ordered = sorted(mapping.items())
        except TypeError:
            ordered = sorted(mapping.items(), key=lambda kv: repr(kv[0]))

        safe = []
        for name, value in ordered:
            try:
                repr(value)
            except Exception:
                value = '<%s:%s>' % (type(value).__name__, id(value))
            safe.append((name, value))
        try:
            return repr(dict(safe))
        except Exception:
            return repr([(name, repr(value)) for name, value in safe])

    def _calculate_key(self, func, cached_key=None, *args, **kwargs):
        '''
        Calculates the cache key based on the function, inputs, and object
        settings.

        :param code func: The function being cached
        :param str cached_key: The `keyed_cache`, if any
        :param *args: Any ``*args`` used to call the function
        :param *kwargs: Any ``*kwargs`` used to call the function
        '''
        if cached_key:
            return cached_key

        try:
            plain, bound = self._bind_arguments(func, args, kwargs)
            rendered = self._render_mapping(bound)
            name = getattr(plain, '__name__', None) or getattr(func, '__name__', 'func')
        except Exception:
            plain = _function_of(func) or func
            name = getattr(plain, '__name__', 'func')
            rendered = repr((
                name,
                len(args),
                tuple(type(arg).__name__ for arg in args),
                tuple(sorted(kwargs)),
            ))

        if self._hashing:
            formatted_key = sha224(str(rendered).encode('utf-8')).hexdigest()
        else:
            formatted_key = str(rendered)

        return "{prefix}{name}{join}{formatted_key}".format(
            join=self._key_join,
            prefix=(self._prefix + self._key_join) if self._prefix else '',
            name=name,
            formatted_key=formatted_key
        )

    def _update_counter(self, key):
        '''Keeps track of cache hits'''
        if not self._debug:
            return

        with self._gc_lock:
            if key in self.counters:
                self.counters[key] += 1
            else:
                self.counters[key] = 1

    def _gc(self):
        '''
        This is the garbage collection thread that periodically calls our
        collect method.
        '''
        tnext = time.time() + self._gc_thread_wait
        while self._do_gc_thread:
            if time.time() > tnext:
                self.collect()
                tnext = time.time() + self._gc_thread_wait

            time.sleep(1)

    def _deadline(self, key, item):
        if key in self._expiry:
            return self._expiry[key]
        timeout = getattr(item, 'timeout', None)
        if not timeout:
            return None
        return self._from_timestamp(timeout)

    def _is_fresh(self, key, item):
        try:
            deadline = self._deadline(key, item)
        except (AttributeError, ValueError, TypeError, OverflowError):
            return False
        if not deadline:
            return True
        return time.time() <= deadline

    def collect(self, since=None):
        '''
        Clear any item from the cache that has timed out.
        '''
        remove_keys = []
        now = time.time()
        for key, item in self.items():
            try:
                deadline = self._deadline(key, item)
                timed_out = bool(deadline and now > deadline)
                added_after_since = False
                if since and getattr(item, 'time_added', None):
                    added_after_since = self._from_timestamp(item.time_added) > since
            except (AttributeError, ValueError, TypeError, OverflowError):
                continue

            if timed_out or added_after_since:
                self._debug_print('collecting : %s' % key)
                remove_keys.append(key)

        for key in remove_keys:
            try:
                del self[key]
            except KeyError:
                pass

    def _remember(self, cache_key, value, timeout):
        '''Store one entry and its exact expiry.'''
        if timeout:
            deadline = time.time() + float(timeout)
            timeout_text = self._to_timestamp(deadline)
        else:
            deadline = None
            timeout_text = None
        result = CachedItem(
            value=value,
            timeout=timeout_text,
            time_added=self._to_timestamp())
        with self._gc_lock:
            self._data_store[cache_key] = result
            self._expiry[cache_key] = deadline
        return result

    # Decorators ##############################################################
    def clear_cache(self):
        '''
        A decorator used to clear the cache everytime the function is called.

        For example, let's say you have a "discovery" function that stores
        data read by other functions, and those function use caching.  You want
        to use ``@c.clear_cache()`` for your main function so you don't have
        to worry about cache being stale.
        '''
        def real_decorator(function):
            @wraps(function)
            def wrapper(*args, **kwargs):
                self.clear()
                return function(*args, **kwargs)
            return wrapper
        return real_decorator

    def cached(self, key=None, timeout=None):
        '''
        A decorator used to memoize the return of a function call.

        Usable as ``@cache.cached``, ``@cache.cached()``,
        ``@cache.cached(key='...', timeout=60)``, or on an already bound
        method (``self.cache.cached()(self.method)``).
        '''
        # ``@cache.cached`` passes the callable in as the first argument.
        direct_original = None
        direct_descriptor = None
        if _function_of(key) is not None:
            direct_original = key
            if isinstance(key, (classmethod, staticmethod)):
                direct_descriptor = type(key)
            key = None
            timeout = None

        if timeout and not isinstance(timeout, int):
            raise ValueError("timeout can only be `int`")
        elif (key in self) or self._is_key_initialized(key):
            # `key in self` will return False if the key either doesn't exist,
            # or it's set to the INIT value.  Therefore, we need to call
            # `_is_key_initialized()` to check that condition.
            raise ValueError("cache key '%s' already exists" % key)
        elif key:
            # Set the default value so we can check for collisions when the
            # next decorator is called.
            self[key] = INIT_CACHE_VALUE

        def real_decorator(function, timeout=timeout):
            outer_type = None
            bound_instance = _bound_self(function)
            if isinstance(function, (classmethod, staticmethod)):
                outer_type = type(function)
                unwrapped = _function_of(function)
                if unwrapped is not None:
                    function = unwrapped
            elif isinstance(function, types.MethodType):
                unwrapped = _function_of(function)
                if unwrapped is not None:
                    function = unwrapped

            # Bound methods reject arbitrary attributes; keep the timeout on
            # the underlying function.
            function.__cached_timeout__ = timeout or self._default_timeout

            @wraps(function)
            def wrapper(*args, **kwargs):
                # A method grabbed off an instance is bound, but the wrapper
                # stored on that instance is not.  Put the instance back so the
                # call succeeds and can be cached.  A normal decorated method
                # already receives ``self`` from the descriptor.
                if bound_instance is not None and (not args or args[0] is not bound_instance):
                    invoke_args = (bound_instance,) + tuple(args)
                else:
                    invoke_args = args

                if not self._cache:
                    return function(*invoke_args, **kwargs)

                cache_key = self._calculate_key(function, key, *invoke_args, **kwargs)

                if self._override_timeout is not None:
                    effective_timeout = self._override_timeout
                else:
                    effective_timeout = function.__cached_timeout__

                cached_item = None
                try:
                    if cache_key in self and (self[cache_key] is not INIT_CACHE_VALUE):
                        cached_item = self[cache_key]
                except KeyError:  # pragma: nocover
                    # Workaround for threading issues, as opposed to a potential
                    # lock block.  A thread may have deleted this key, and
                    # that's fine.  We simply need to cache it again.
                    # We won't always hit this, so we disable code coverage.
                    self._debug_print('KeyError %s' % cache_key)

                if cached_item is not None and self._is_fresh(cache_key, cached_item):
                    self._debug_print('cache hit : %s' % cache_key)
                    self._update_counter(cache_key)
                    return cached_item.value

                if cached_item is not None:
                    self._debug_print('cache timeout: %s' % cache_key)
                else:
                    self._debug_print('caching %s' % cache_key)

                result = self._remember(
                    cache_key,
                    function(*invoke_args, **kwargs),
                    effective_timeout)
                return result.value

            if outer_type is not None:
                return outer_type(wrapper)
            return wrapper

        if direct_original is not None:
            target = direct_original
            if direct_descriptor is not None:
                target = _function_of(direct_original) or direct_original
            wrapped = real_decorator(target)
            if direct_descriptor is not None:
                return direct_descriptor(wrapped)
            return wrapped
        return real_decorator

    def serialize(self, filename):
        '''
        Serialize the cache to a filename.  This process uses ``pickle``; Do
        not use this function if you are caching something that is not
        picklable!
        '''
        with self._gc_lock:
            payload = dict(self._data_store)
        with open(filename, 'wb') as fh:
            pickle.dump(payload, fh, -1)

    def deserialize(self, filename):
        '''
        Read the serialized cache data from a file.
        '''
        with open(filename, 'rb') as fh:
            data = pickle.load(fh)
        with self._gc_lock:
            self._data_store = data
            self._expiry.clear()

#!/usr/bin/env python
# coding: utf-8
'''
yamicache : Yet another in-memory cache module ('yami' sounds better to me than
'yaim')

This module provides a simple in-memory interface for caching results from
function calls.
'''

# Imports #####################################################################
from __future__ import print_function
import json
import time
import inspect
import types
import contextlib
import collections
from hashlib import sha224
from functools import wraps
from threading import RLock, Thread
try:
    import cPickle as pickle
except ImportError:
    import pickle
try:
    from collections.abc import MutableMapping
except ImportError:  # pragma: no cover
    from collections import MutableMapping


# Globals #####################################################################
__all__ = ['Cache', 'nocache', 'override_timeout']

_ASCTIME_MONTHS = {
    'Jan': 1, 'Feb': 2, 'Mar': 3, 'Apr': 4, 'May': 5, 'Jun': 6,
    'Jul': 7, 'Aug': 8, 'Sep': 9, 'Oct': 10, 'Nov': 11, 'Dec': 12,
}
_PRIMITIVES = (type(None), bool, int, float, str, bytes)


def _function_of(obj):
    '''Plain function for a function, method, classmethod, or staticmethod.'''
    if obj is None:
        return None
    if isinstance(obj, types.FunctionType):
        return obj
    if isinstance(obj, types.MethodType):
        return getattr(obj, '__func__', None) or getattr(obj, 'im_func', None)
    if isinstance(obj, (classmethod, staticmethod)):
        func = getattr(obj, '__func__', None)
        if isinstance(func, types.FunctionType):
            return func
        try:
            got = obj.__get__(None, type)
        except Exception:
            return None
        if isinstance(got, types.MethodType):
            return getattr(got, '__func__', None) or getattr(got, 'im_func', None)
        if isinstance(got, types.FunctionType):
            return got
    return None


def _bound_owner(obj):
    '''Instance or class a method is already bound to.'''
    if isinstance(obj, types.MethodType):
        owner = getattr(obj, '__self__', None)
        if owner is None:
            owner = getattr(obj, 'im_self', None)
        return owner
    return None


@contextlib.contextmanager
def override_timeout(cache_obj, timeout):
    cache_obj._override_timeout = timeout

    try:
        yield
    finally:
        # The value of ``None`` disable the override timeout mechanism
        cache_obj._override_timeout = None


@contextlib.contextmanager
def nocache(cache_obj):
    '''
    Use this context manager to temporarily disable all caching for an
    object.

    Example:

        >>> from yamicache import Cache, nocache
        >>> c = Cache()
        >>> @c.cached
        ... def test():
        ...     return 4
        ...
        >>> with nocache(c):
        ...     test()
        ...
        4
        >>> print(c.data_store)
        {}
        >>>

    '''
    cache_obj._cache = False

    try:
        yield
    finally:
        cache_obj._cache = True


CachedItem = collections.namedtuple('CachedItem', 'value timeout time_added')
INIT_CACHE_VALUE = CachedItem("<value not cached yet>", None, None)


class Cache(MutableMapping):
    '''
    A class for caching and retreiving returns from function calls.

    :param bool hashing: Whether or not to hash the function inputs when
        calculating the key.  This helps keep the keys *readable*, especially
        for functions with many inputs.
    :param str key_join: The character used to join the different parts that
        make up the hash key.
    :param bool debug: When ``True``, ``Cache.counters`` will be enabled and
        cache hits will produce output on ``stdout``.
    :param str prefix: All cache keys will use this prefix.  Since the current
        implementation is instance-based, this is only helpful if dumping or
        comparing the cache to another instance.
    :param bool quiet: Don't print during ``debug`` cache hits
    :param int default_timeout: If > 0, all cached items will be considered
        stale this many seconds after they are cached.  In that case, the
        function will be run again, cached, and a new timeout value will be
        created.
    :param int gc_thread_wait: The number of seconds in between cache
        *garbage collection*.  The default, ``None``, will disable the garbage
        collection thread.  This parameter is only valid if ``default_timeout``
        is > 0 (``ValueError`` is raised otherwise).
    '''
    def __init__(
        self, hashing=True, key_join='|', debug=False, prefix=None,
        quiet=False, default_timeout=0, gc_thread_wait=None
    ):
        self._prefix = prefix or ''
        self._hashing = hashing
        self._key_join = key_join
        self._debug = debug
        self._quiet = quiet
        self._cache = True  # Allow for ``nocache``
        self._data_store = {}
        # Exact deadlines.  asctime() is whole seconds and can mark a fresh
        # entry expired, so repeated calls never register as hits.
        self._deadlines = {}
        self._default_timeout = default_timeout
        self._gc_thread_wait = gc_thread_wait
        self._gc_thread = None
        self._do_gc_thread = False
        self._gc_lock = RLock()
        self.counters = {}  # Only enabled with ``debug``

        # Force all calls to use this value instead of default, or what was
        # used during decorator creation.
        self._override_timeout = None

        if default_timeout and not isinstance(default_timeout, int):
            raise ValueError("Default timeout can only be `int`")

        if self._gc_thread_wait and not default_timeout:
            raise ValueError("gc_thread_wait is only valid if default_timeout is > 0")

        if self._gc_thread_wait:
            self._do_gc_thread = True
            self._gc_thread = Thread(target=self._gc)
            self._gc_thread.daemon = True
            self._gc_thread.start()

    # Default stuff to override MutableMapping ABC ############################
    def __len__(self):
        return len([x for x, y in self.items() if y is not INIT_CACHE_VALUE])

    def __getitem__(self, key):
        '''Only return the item if it's not the INIT value'''
        with self._gc_lock:
            if (key not in self._data_store) or (self._data_store[key] is INIT_CACHE_VALUE):
                raise KeyError(key)
            return self._data_store[key]

    def __setitem__(self, key, value):
        with self._gc_lock:
            self._data_store[key] = value

    def __delitem__(self, key):
        with self._gc_lock:
            del self._data_store[key]
            self._deadlines.pop(key, None)

    def __iter__(self):
        '''
        Override ``iter()``.  Copy keys first so iteration cannot deadlock.
        '''
        with self._gc_lock:
            keys = list(self._data_store.keys())
        for x in keys:
            yield x

    # Override some of the *normal* methods to include the lock ###############
    def clear(self):
        '''Drop cached entries and keep caching enabled.'''
        with self._gc_lock:
            self._data_store.clear()
            self.counters.clear()
            self._deadlines.clear()
            self._cache = True

    def keys(self):
        '''Return a list of keys in the cache'''
        with self._gc_lock:
            return list(self._data_store.keys())

    def items(self):
        '''Return all items in the cache as a list of ``tuple(key, value)``'''
        with self._gc_lock:
            return list(self._data_store.items())

    def values(self):
        '''Return a list of cached values'''
        with self._gc_lock:
            return list(self._data_store.values())

    def pop(self, key):
        '''Remove the cached value specified by ``key``'''
        with self._gc_lock:
            self._deadlines.pop(key, None)
            return self._data_store.pop(key)

    def popitem(self):
        '''Remove a random item from the cache (only useful during testing)'''
        with self._gc_lock:
            item = self._data_store.popitem()
            self._deadlines.pop(item[0], None)
            return item
    ###########################################################################

    @property
    def data_store(self):
        '''Underlying cache mapping (includes not-yet-filled placeholders).'''
        return self._data_store

    @data_store.setter
    def data_store(self, value):
        with self._gc_lock:
            self._data_store = value
            self._deadlines.clear()

    def _is_key_initialized(self, key):
        with self._gc_lock:
            return self._data_store.get(key) is INIT_CACHE_VALUE

    def _from_timestamp(self, timestamp):
        '''Convert a timestamp string to an epoch value'''
        if isinstance(timestamp, (int, float)) and not isinstance(timestamp, bool):
            return float(timestamp)

        text = str(timestamp).strip()
        try:
            return time.mktime(time.strptime(text))
        except (TypeError, ValueError):
            pass

        parts = text.split()
        if len(parts) >= 5 and parts[1] in _ASCTIME_MONTHS:
            year = int(parts[4])
            month = _ASCTIME_MONTHS[parts[1]]
            day = int(parts[2])
            hour, minute, second = [int(piece) for piece in parts[3].split(':')]
            return time.mktime((year, month, day, hour, minute, second, 0, 0, -1))

        return time.mktime(time.strptime(text))

    def _to_timestamp(self, epoch=None):
        '''Convert an epoch value to a timestamp string'''
        if epoch:
            return time.asctime(time.localtime(epoch))

        return time.asctime()

    def _debug_print(self, *args):
        if self._debug and not self._quiet:
            print(*args)

    def dump(self):
        '''Dump the entire cache as a JSON string'''
        return json.dumps(self._data_store, indent=4, separators=(',', ': '))

    def _identity(self, value):
        if isinstance(value, type):
            label = value.__name__
        else:
            label = type(value).__name__
        return '<%s id=%s>' % (label, id(value))

    def _bind_arguments(self, func, args, kwargs):
        '''
        Build the argument map for a call.

        Bound methods are often wrapped and then called without ``self``
        (``cache.cached()(self.method)(arg)``).  The instance is put back so
        the call and the cache key both see it.  The instance is stored by id:
        ``repr(self)`` changes when the object changes and then every call
        misses, leaving counters empty.  A raising ``repr`` used to abort
        before the value was stored at all.
        '''
        owner = _bound_owner(func)
        plain = _function_of(func) or func
        if not hasattr(plain, '__code__') and hasattr(plain, '__func__'):
            plain = plain.__func__

        if owner is not None and (not args or args[0] is not owner):
            args = (owner,) + tuple(args)

        key = {}
        fargs = []
        varargs_name = None
        try:
            getter = getattr(inspect, 'getfullargspec', None) or inspect.getargspec
            spec = getter(plain)
            fargs = list(spec.args)
            defaults = spec.defaults
            kwdefaults = getattr(spec, 'kwonlydefaults', None)
            varargs_name = getattr(spec, 'varargs', None)
        except (TypeError, ValueError, AttributeError):
            code = getattr(plain, '__code__', None)
            if code is not None:
                fargs = list(code.co_varnames[:code.co_argcount])
            defaults = None
            kwdefaults = None

        if defaults and fargs:
            key.update(dict(zip(fargs[-len(defaults):], defaults)))
        if kwdefaults:
            key.update(kwdefaults)
        for name, value in kwargs.items():
            key[name] = value
        for name, value in zip(fargs, args):
            key[name] = value
        if varargs_name and len(args) > len(fargs):
            key[varargs_name] = tuple(args[len(fargs):])

        stable = {}
        for name, value in key.items():
            try:
                if (
                    (owner is not None and value is owner) or
                    (name in ('self', 'cls') and not isinstance(value, _PRIMITIVES))
                ):
                    stable[name] = self._identity(value)
                else:
                    stable[name] = value
            except Exception:
                stable[name] = self._identity(value)
        return plain, args, stable

    def _calculate_key(self, func, cached_key=None, *args, **kwargs):
        '''
        Calculates the cache key based on the function, inputs, and object
        settings.

        :param code func: The function being cached
        :param str cached_key: The `keyed_cache`, if any
        :param *args: Any ``*args`` used to call the function
        :param *kwargs: Any ``*kwargs`` used to call the function
        '''
        if cached_key:
            return cached_key

        try:
            plain, _args, bound = self._bind_arguments(func, args, kwargs)
            try:
                ordered = sorted(bound.items())
            except TypeError:
                ordered = sorted(bound.items(), key=lambda kv: repr(kv[0]))
            safe = []
            for name, value in ordered:
                try:
                    repr(value)
                except Exception:
                    value = self._identity(value)
                safe.append((name, value))
            rendered = repr(dict(safe))
            name = getattr(plain, '__name__', 'func')
        except Exception:
            plain = _function_of(func) or func
            name = getattr(plain, '__name__', 'func')
            safe_args = []
            for arg in args:
                if isinstance(arg, _PRIMITIVES):
                    safe_args.append(arg)
                else:
                    safe_args.append(self._identity(arg))
            rendered = repr((tuple(safe_args), tuple(sorted(kwargs.items()))))

        if self._hashing:
            formatted_key = sha224(str(rendered).encode('utf-8')).hexdigest()
        else:
            formatted_key = str(rendered)

        return "{prefix}{name}{join}{formatted_key}".format(
            join=self._key_join,
            prefix=(self._prefix + self._key_join) if self._prefix else '',
            name=name,
            formatted_key=formatted_key
        )

    def _update_counter(self, key):
        '''Keeps track of cache hits'''
        if not self._debug:
            return

        with self._gc_lock:
            if key in self.counters:
                self.counters[key] += 1
            else:
                self.counters[key] = 1

    def _gc(self):
        '''
        This is the garbage collection thread that periodically calls our
        collect method.
        '''
        tnext = time.time() + self._gc_thread_wait
        while self._do_gc_thread:
            if time.time() > tnext:
                self.collect()
                tnext = time.time() + self._gc_thread_wait

            time.sleep(1)

    def _deadline_for(self, key, item):
        if key in self._deadlines:
            return self._deadlines[key]
        timeout = getattr(item, 'timeout', None)
        if not timeout:
            return None
        return self._from_timestamp(timeout)

    def collect(self, since=None):
        '''
        Clear any item from the cache that has timed out.
        '''
        remove_keys = []
        now = time.time()
        for key, item in self.items():
            try:
                deadline = self._deadline_for(key, item)
                timed_out = bool(deadline and now > deadline)
                added_after_since = False
                if since and getattr(item, 'time_added', None):
                    added_after_since = self._from_timestamp(item.time_added) > since
            except (AttributeError, ValueError, TypeError, OverflowError):
                continue

            if timed_out or added_after_since:
                self._debug_print('collecting : %s' % key)
                remove_keys.append(key)

        for key in remove_keys:
            try:
                del self[key]
            except KeyError:
                pass

    def _store(self, cache_key, value, timeout):
        if timeout:
            deadline = time.time() + float(timeout)
            shown = self._to_timestamp(deadline)
        else:
            deadline = None
            shown = None
        result = CachedItem(value=value, timeout=shown, time_added=self._to_timestamp())
        with self._gc_lock:
            self._data_store[cache_key] = result
            self._deadlines[cache_key] = deadline
        return result

    # Decorators ##############################################################
    def clear_cache(self):
        '''
        A decorator used to clear the cache everytime the function is called.

        For example, let's say you have a "discovery" function that stores
        data read by other functions, and those function use caching.  You want
        to use ``@c.clear_cache()`` for your main function so you don't have
        to worry about cache being stale.
        '''
        def real_decorator(function):
            @wraps(function)
            def wrapper(*args, **kwargs):
                self.clear()
                return function(*args, **kwargs)
            return wrapper
        return real_decorator

    def cached(self, key=None, timeout=None):
        '''
        A decorator used to memoize the return of a function call.

        Usable as ``@cache.cached``, ``@cache.cached()``,
        ``@cache.cached(key='...', timeout=60)``, or directly on a bound
        method::

            self.cache.cached()(self.method)(arg)
        '''
        direct = None
        direct_kind = None
        if _function_of(key) is not None:
            direct = key
            if isinstance(key, (classmethod, staticmethod)):
                direct_kind = type(key)
            key = None
            timeout = None

        if timeout and not isinstance(timeout, int):
            raise ValueError("timeout can only be `int`")
        elif (key in self) or self._is_key_initialized(key):
            # `key in self` will return False if the key either doesn't exist,
            # or it's set to the INIT value.  Therefore, we need to call
            # `_is_key_initialized()` to check that condition.
            raise ValueError("cache key '%s' already exists" % key)
        elif key:
            # Set the default value so we can check for collisions when the
            # next decorator is called.
            self[key] = INIT_CACHE_VALUE

        def real_decorator(function, timeout=timeout):
            outer_kind = None
            owner = _bound_owner(function)
            if isinstance(function, (classmethod, staticmethod)):
                outer_kind = type(function)
                unwrapped = _function_of(function)
                if unwrapped is not None:
                    function = unwrapped
            elif owner is not None:
                unwrapped = _function_of(function)
                if unwrapped is not None:
                    function = unwrapped

            try:
                function.__cached_timeout__ = timeout or self._default_timeout
            except AttributeError:
                # Some callables refuse attributes; the default still applies.
                function.__dict__[
                    '__cached_timeout__'
                ] = timeout or self._default_timeout

            cached_timeout = getattr(
                function, '__cached_timeout__', timeout or self._default_timeout)

            @wraps(function)
            def wrapper(*args, **kwargs):
                # Reattach the instance when this wrapper was built from a
                # bound method and then called like a plain function.
                if owner is not None and (not args or args[0] is not owner):
                    call_args = (owner,) + tuple(args)
                else:
                    call_args = args

                if not self._cache:
                    return function(*call_args, **kwargs)

                cache_key = self._calculate_key(function, key, *call_args, **kwargs)

                if self._override_timeout is not None:
                    effective = self._override_timeout
                else:
                    effective = getattr(function, '__cached_timeout__', cached_timeout)

                found = None
                try:
                    if cache_key in self and (self[cache_key] is not INIT_CACHE_VALUE):
                        found = self[cache_key]
                except KeyError:  # pragma: nocover
                    # Workaround for threading issues, as opposed to a potential
                    # lock block.  A thread may have deleted this key, and
                    # that's fine.  We simply need to cache it again.
                    # We won't always hit this, so we disable code coverage.
                    self._debug_print('KeyError %s' % cache_key)

                fresh = False
                if found is not None:
                    try:
                        deadline = self._deadlines.get(cache_key, None)
                        if deadline is None and found.timeout:
                            deadline = self._from_timestamp(found.timeout)
                        fresh = (deadline is None) or (time.time() <= deadline)
                    except (ValueError, TypeError, OverflowError):
                        fresh = False

                if found is not None and fresh:
                    self._debug_print('cache hit : %s' % cache_key)
                    self._update_counter(cache_key)
                    return found.value

                if found is not None:
                    self._debug_print('cache timeout: %s' % cache_key)
                else:
                    self._debug_print('caching %s' % cache_key)

                value = function(*call_args, **kwargs)
                if effective:
                    deadline = time.time() + float(effective)
                    timeout_text = self._to_timestamp(deadline)
                else:
                    deadline = None
                    timeout_text = None
                stored = CachedItem(
                    value=value,
                    timeout=timeout_text,
                    time_added=self._to_timestamp())
                with self._gc_lock:
                    self._data_store[cache_key] = stored
                    self._deadlines[cache_key] = deadline
                return value

            if outer_kind is not None:
                return outer_kind(wrapper)
            return wrapper

        if direct is not None:
            wrapped = real_decorator(direct)
            if direct_kind is not None:
                return direct_kind(wrapped)
            return wrapped
        return real_decorator

    def serialize(self, filename):
        '''
        Serialize the cache to a filename.  This process uses ``pickle``; Do
        not use this function if you are caching something that is not
        picklable!
        '''
        with self._gc_lock:
            payload = dict(self._data_store)
        with open(filename, 'wb') as fh:
            pickle.dump(payload, fh, -1)

    def deserialize(self, filename):
        '''
        Read the serialized cache data from a file.
        '''
        with open(filename, 'rb') as fh:
            data = pickle.load(fh)
        with self._gc_lock:
            self._data_store = data
            self._deadlines.clear()

